 yAxis:{type:'value',min:yMin,max:yMax,axisLine:{show:false},axisTick:{show:false},axisLabel:{color:'#7e8694',fontSize:11,formatter:(v)=>v.toFixed(1)},splitLine:{show:true,lineStyle:{color:'rgba(255,255,255,0.055)'}}},
 series:[
  {name:'pts',type:'scatter',symbolSize:7,data:scatter,z:2,emphasis:{disabled:true}},
  {name:'avg',type:'line',showSymbol:false,smooth:true,connectNulls:true,data:ma,lineStyle:{color:'#F59E0B',width:2.5},itemStyle:{color:'#F59E0B'},z:3,emphasis:{disabled:true},
   markLine:{silent:true,symbol:'none',data:REF.map(r=>({yAxis:r.y,lineStyle:{color:r.color,type:'dashed',width:1.2},label:{formatter:r.y.toFixed(1),color:r.color,position:'insideEndTop',fontSize:10}}))}}
 ]
};

const ctx=(typeof context!=='undefined'&&context)?context:{};
const pd=(ctx.panel&&ctx.panel.data)||ctx.data||(typeof data!=='undefined'?data:null);
const series_in=(pd&&pd.series)||[];
const W=(ctx.panel&&ctx.panel.width)?ctx.panel.width:1900;
const H=(ctx.panel&&ctx.panel.height)?ctx.panel.height:190;
const vget=(f)=>f?(f.values&&f.values.toArray?f.values.toArray():f.values):[];
const byRef={}; for(const fr of series_in){ if(fr&&fr.refId!=null) byRef[fr.refId]=fr; }
const readFrame=(fr)=>{ if(!fr||!fr.fields) return []; const tf=fr.fields.find(x=>x.type==='time'); const vf=fr.fields.find(x=>x.type==='number'&&x!==tf)||fr.fields.find(x=>x.type==='number'); const ts=vget(tf),vs=vget(vf); let p=[]; for(let i=0;i<vs.length;i++){ if(vs[i]!=null){ p.push([ ts&&ts[i]!=null?+ts[i]:i, +vs[i] ]); } } p.sort((a,b)=>a[0]-b[0]); return p; };
const tierOf=(tiers,v)=>{ let r=tiers[0]; for(const t of tiers){ if(v>=t[0]) r=t; } return r; };
const FNT='Inter, system-ui, sans-serif';
const M=[
 {ref:'A',label:'VO2max',unit:'',dec:1,tiers:[[0,'#F85454','Poor'],[41.7,'#FD9D39','Fair'],[45.4,'#40C35D','Good'],[51.1,'#3B97F3','Excellent'],[55.4,'#6F42F3','Superior']]},
 {ref:'B',label:'Endurance Score',unit:'',dec:0,tiers:[[0,'#E02C2C','Recreational'],[5100,'#F27716','Intermediate'],[5800,'#FD9D39','Trained'],[6600,'#40C35D','Well-trained'],[7300,'#3B97F3','Expert'],[8100,'#6F42F3','Superior'],[8800,'#DE45C6','Elite']]},
 {ref:'C',label:'Hill Score',unit:'',dec:0,tiers:[[0,'#C92A2A','Recreational'],[25,'#E8590C','Challenger'],[50,'#2FA45A','Trained'],[70,'#1C7ED6','Skilled'],[85,'#7C5CFC','Expert'],[95,'#C026D3','Elite']]},
 {ref:'D',label:'Fitness Age',unit:'y',dec:1,color:'#4ADE80'},
 {ref:'E',label:'Poids',unit:'kg',dec:1,color:'#A3E635'},
 {ref:'F',label:'FCmax',unit:'bpm',dec:0,color:'#60A5FA'},
 {ref:'G',label:'LTHR',unit:'bpm',dec:0,color:'#FB923C'},
 {ref:'H',label:'FC repos',unit:'bpm',dec:0,color:'#4ADE80'},
 {ref:'I',label:'FTP',unit:'W',dec:0,color:'#C084FC'},
 {ref:'J',label:'Δ poids 30j',unit:'kg',dec:1,color:'#60A5FA',signed:true}
];
const COLS=5,ROWS=2,P=12,G=12;
const cardW=(W-2*P-(COLS-1)*G)/COLS, cardH=(H-2*P-(ROWS-1)*G)/ROWS;
const fmt=(v,d)=> d>0? v.toFixed(d): Math.round(v).toString();
let g=[];
M.forEach((m,idx)=>{
  const c=idx%COLS, r=Math.floor(idx/COLS);
  const cx=P+c*(cardW+G), cy=P+r*(cardH+G);
  g.push({type:'rect',z:0,silent:true,shape:{x:cx,y:cy,width:cardW,height:cardH,r:10},style:{fill:'rgba(255,255,255,0.025)',stroke:'rgba(255,255,255,0.07)',lineWidth:1}});
  const pts=readFrame(byRef[m.ref]);
  let val=null; if(pts.length) val=pts[pts.length-1][1];
  let accent=m.color||'#9aa0a6', tlabel=null;
  if(m.tiers&&val!=null){ const t=tierOf(m.tiers,val); accent=t[1]; tlabel=t[2]; }
  g.push({type:'text',z:5,silent:true,style:{x:cx+15,y:cy+12,text:m.label,fill:'#8b94a0',font:'500 12px '+FNT,textVerticalAlign:'top'}});
  const fsz=Math.min(30,Math.max(20,Math.round(cardH*0.32)));
  const valY=cy+Math.round(cardH*0.30);
  const vs= val==null? '—' : ((m.signed&&val>0?'+':'')+fmt(val,m.dec));
  g.push({type:'text',z:6,silent:true,style:{x:cx+15,y:valY,text:vs,fill:accent,font:'700 '+fsz+'px '+FNT,textAlign:'left',textVerticalAlign:'top'}});
  let cursorX=cx+15+vs.length*fsz*0.56+6;
  if(m.unit&&val!=null){ g.push({type:'text',z:6,silent:true,style:{x:cursorX,y:valY+fsz-14,text:m.unit,fill:'#7e8694',font:'500 13px '+FNT,textVerticalAlign:'top'}}); cursorX+=m.unit.length*8+8; }
  if(tlabel){ const pw=tlabel.length*6.4+16; g.push({type:'rect',z:4,silent:true,shape:{x:cursorX,y:valY+2,width:pw,height:18,r:9},style:{fill:accent+'26'}}); g.push({type:'text',z:5,silent:true,style:{x:cursorX+pw/2,y:valY+11,text:tlabel,fill:accent,font:'600 10px '+FNT,textAlign:'center',textVerticalAlign:'middle'}}); }
  if(pts.length>=2){
    const sH=Math.max(14,Math.round(cardH*0.24)), sTop=cy+cardH-sH-8, sX=cx+15, sW=cardW-30;
    const ys=pts.map(p=>p[1]); let mn=Math.min.apply(null,ys),mx=Math.max.apply(null,ys);
    const t0=pts[0][0], t1=pts[pts.length-1][0];
    const sx=(t)=> t1>t0? sX+(t-t0)/(t1-t0)*sW : sX+sW/2;
    const sy=(v)=> mx>mn? sTop+sH-(v-mn)/(mx-mn)*sH : sTop+sH/2;
    const lp=pts.map(p=>[sx(p[0]),sy(p[1])]);
    const poly=lp.concat([[lp[lp.length-1][0],sTop+sH],[lp[0][0],sTop+sH]]);
    g.push({type:'polygon',z:1,silent:true,shape:{points:poly},style:{fill:accent+'2a'}});
    g.push({type:'polyline',z:2,silent:true,shape:{points:lp},style:{stroke:accent,lineWidth:2,fill:'none'}});
  }
});
return {backgroundColor:'transparent',animation:false,graphic:g,series:[]};
